const SearchUploadNavigator = () => {
  return (
    <Stack.Navigator mode="modal" initialRouteName="SearchScreen">
      <Stack.Screen
        name="SearchScreen"
        component={VideoList}
        options={{
          headerStyle: {
            backgroundColor: '#f4511e',
          },
          headerTintColor: '#fff',
          headerLeft: (props) => (
            <UploadHeader {...props} title="YouTube Search" />
          ),
          title: '', // Override default title
        }}
      />
      <Stack.Screen
        name="Upload"
        component={Upload}
        options={{
          headerStyle: {
            backgroundColor: '#f4511e',
          },
          headerTintColor: '#fff',
          headerLeft: (props) => (
            <UploadHeader {...props} title="Upload a Video" />
          ),
          title: '',
        }}
      />
    </Stack.Navigator>
  );
};

